window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II et phrases avec wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si j'étais toi, je …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La réalité d'Eva – les souhaits d'Eva. Complétez : würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Elle aimerait pourtant être plus grande.","why":"*grösser sein* : la forme de souhait de *sein* est **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Elle aimerait pourtant bien parler espagnol.","why":"Un infinitif se trouve à la fin (*sprechen*), donc le souhait se forme avec **würde** + infinitif.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Elle préférerait pourtant travailler comme guide touristique.","why":"Infinitif à la fin (*arbeiten*) → **würde** + infinitif. *lieber* = plutôt.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Elle aimerait pourtant avoir un grand appartement.","why":"*eine Wohnung haben* : la forme de souhait de *haben* est **hätte**. Pas besoin d'infinitif.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"À quoi pensent ces personnes ?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque image à une expression de l'encadré.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si je ne devais pas travailler, je serais assis au jardin en ce moment.","why":"L'image 1 le montre en train de travailler, puis rêvant sur une chaise longue. Après une subordonnée en *wenn*, la principale commence par le verbe (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si j'avais une voiture, je ne devrais pas faire du vélo sous la pluie.","why":"Il fait du vélo sous la pluie ; une voiture lui éviterait cela. *müsste* est le Konjunktiv II de *müssen*. *Velo* est le mot suisse pour *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si le bus n'avait pas de retard, je serais à l'heure au bureau.","why":"Un bus en retard la met en retard au travail. *wäre* est le Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Réécrivez les phrases de a : commencez par la principale, puis la subordonnée en wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Je ne devrais pas faire du vélo sous la pluie si j'avais une voiture.","why":"D'abord la principale, puis la subordonnée en *wenn*. Dans la subordonnée en *wenn*, le verbe (*hätte*) va à la fin.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Je serais à l'heure au bureau si le bus n'avait pas de retard.","why":"Même schéma : principale, virgule, *wenn* … verbe à la fin (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Complétez avec les mots de l'encadré. Chaque mot est utilisé une fois ; les mots barrés sont utilisés dans l'exemple.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Je ferais certaines choses autrement si j'étais la cheffe de notre entreprise.","why":"*machen* à la fin → **würde** + infinitif. *Chefin sein* → **wäre**, à la fin de la subordonnée en *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si j'étais Marco, je ferais absolument une formation professionnelle.","why":"*Marco sein* → **wäre** (comme *Wenn ich du wäre …*). La principale a l'infinitif *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si je pouvais décider librement, je travaillerais dans une petite entreprise.","why":"*frei entscheiden können* → **könnte** à la fin de la subordonnée en *wenn*. Principale avec *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si nous avions des enfants, je ne devrais travailler qu'à mi-temps.","why":"*Kinder haben* avec *wir* → **hätten**. L'encadré laisse **müsste** pour le dernier trou.","source":"k2","check":"*müsste* et *würde* sont tous deux corrects en b, c et e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* est tout aussi bon). L'encadré indique seulement quels trois trous reçoivent *würde* et lequel reçoit *müsste* ; ce corrigé donne la répartition la plus probable. Demandez à votre enseignant ce que le livre attend."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Je dois me dépêcher à cause de mon travail.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Réécrivez les réponses avec weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Parce que mon amie n'est pas ponctuelle.","why":"*wegen* + nom devient *weil* + une proposition avec un verbe ; le verbe (*ist*) va à la fin.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Parce qu'il fait mauvais.","why":"*des schlechten Wetters* → *das Wetter ist schlecht* ; après *weil*, le verbe va à la fin.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Parce que j'ai un rendez-vous important.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusatif après *haben*) ; verbe à la fin.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Complétez : wegen – weshalb – weil – deswegen – denn. Un mot peut être utilisé plusieurs fois.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Je le comprends mal à cause de sa prononciation.","why":"Un nom suit (*seiner Aussprache*, génitif), pas une proposition → la préposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un jour, j'aimerais bien aller en Italie, car j'aimerais voir la mer.","why":"Le verbe reste en 2e position après le trou (*ich möchte*) → **denn**. Avec *weil*, il irait à la fin.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Je dois améliorer ma compréhension orale, c'est pourquoi je regarde beaucoup de films.","why":"La deuxième partie est la conséquence, et le verbe vient juste après le trou (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mes enfants ont vite appris l'allemand parce qu'à l'école enfantine, ils sont toujours avec des enfants suisses.","why":"Le verbe est à la fin (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Pourquoi écris-tu les mots sur des petites cartes ?","why":"Il faut un mot interrogatif : **Weshalb** signifie *warum* (pourquoi)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Ma sœur parle déjà presque couramment l'allemand, c'est pourquoi elle peut m'aider à apprendre l'allemand.","why":"Conséquence, et le verbe vient juste après le trou (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Au cours de langue. Complétez : weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Je n'ai pas pu faire le dernier exercice parce que je ne l'ai pas compris.","why":"Le verbe est à la fin (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"Il n'y avait personne à l'inscription. C'est pourquoi je suis rentré à la maison.","why":"Une nouvelle phrase qui donne la conséquence, avec le verbe juste après le trou (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"En raison de mes bonnes notes, je n'ai pas dû passer de test au début du cours.","why":"Un groupe nominal suit (*meiner guten Noten*, génitif pluriel) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Il y a un cours de langue supplémentaire parce que de très nombreux participants se sont inscrits.","why":"Le verbe est à la fin (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Hier, je n'ai malheureusement pas pu venir au cours à cause de mon mal de dents.","why":"Un groupe nominal suit (*meiner Zahnschmerzen*, génitif pluriel) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Qui trouve les meilleures excuses ? Choisissez une situation et écrivez. Les réponses modèles ne sont chaque fois qu'une possibilité parmi d'autres.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Malheureusement, je n'ai pas pu ranger la cuisine parce que j'ai soudain eu très mal au dos. J'ai dû m'allonger. C'est pourquoi j'ai regardé un film.","why":"Emploie *weil* (verbe à la fin : *hatte*) et *Deswegen* (verbe juste après : *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"À cause d'une grippe, je ne suis pas allé à l'examen final. J'avais beaucoup de fièvre, c'est pourquoi je suis resté au lit.","why":"Emploie *wegen* + génitif (*einer Grippe*) et *deswegen* + verbe (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Je suis vraiment désolé ! Malheureusement, je suis arrivé en retard, car il y avait un accident sur l'autoroute. À cause de l'embouteillage, j'ai perdu deux heures.","why":"*denn* garde le verbe en 2e position (*war*). *wegen des Staus* : génitif de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (phrases conditionnelles, y compris les irréelles au Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen avec le génitif)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Grandir avec plusieurs langues · lecture, message de forum, mots croisés, mots préférés","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Deux ou trois langues dans une même famille – aucun problème ?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Qui dit quoi ? Lisez les trois textes et écrivez le nom de la personne qui dit chaque phrase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"«Les enfants veulent parler la même langue que leurs amis.» – Janusz","why":"Janusz (texte B) : *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"«C'est bien de parler plusieurs langues très bien, non ?» – Yara","why":"Yara (texte C) : *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"«Mes enfants passent d'une langue à l'autre.» – Amira","why":"Amira (texte A) : *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Elle est la seule à parler de ses propres enfants."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Qu'est-ce qui est juste ? Relisez les textes. Tapez *richtig* (juste) ou *falsch* (faux) après chaque phrase ; dans le livre, vous cochez seulement les phrases justes.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Les enfants d'Amira parlent mieux l'arabe que l'allemand. → juste","why":"La famille parle toujours arabe à la maison : *Darum können das die Kinder viel besser.* (Leur allemand ici est du suisse allemand.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Dans la famille d'Amira, on ne parle qu'allemand. → faux","why":"Le contraire : *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz a appris l'allemand pendant six ans. → faux","why":"Il avait six ans quand la famille a déménagé (*als ich sechs Jahre alt war*), et il parlait couramment le haut allemand après un an."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz et sa sœur ne voulaient pas parler polonais avec leurs parents. → juste","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara parle couramment trois langues. → juste","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* L'allemand est sa quatrième langue, et elle ne le parle pas encore bien."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara va bientôt apprendre l'allemand aussi. → faux","why":"Elle ne commence pas bientôt (*bald*) : elle apprend déjà l'allemand depuis deux ans (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Écrire un message de forum. Vous avez regardé un débat télévisé sur le fait de grandir avec plusieurs langues. Dans le forum en ligne de l'émission, vous trouvez cet avis :","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Prenez des notes sur les quatre questions. De courtes notes suffisent, pas de phrases complètes. Les notes modèles ne sont qu'une possibilité.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Oui : le fils de ma voisine – italien avec sa mère, suisse allemand à l'école","why":"Notes seulement : un nom ou une personne, et quelles langues où."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"apprendre deux langues sans cours, contact avec la famille à l'étranger, avantages au travail","why":"Rassemblez deux ou trois avantages ; vous en avez besoin pour *Ich finde es sehr gut, dass …* en b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mélanger les langues, une langue est plus faible, beaucoup de travail pour les parents","why":"Ces notes vont dans *Es könnte schwierig sein, dass …* et *Auf der anderen Seite …* en b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"non – les enfants apprennent bien deux langues si leurs parents leur parlent beaucoup","why":"Décidez oui ou non et donnez une raison : cela devient *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Écrivez maintenant votre opinion sur le sujet (environ 80 mots). Utilisez vos notes de a et quelques-unes des expressions.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Je ne suis pas d'accord avec Sandra, car beaucoup d'enfants apprennent deux langues sans problèmes. Le fils de ma voisine grandit avec l'italien et l'allemand. Il parle italien avec sa mère et suisse allemand à l'école. Je trouve très bien qu'il apprenne deux langues si tôt. Le fait qu'il mélange parfois les langues pourrait être difficile. D'un autre côté, c'est normal chez les petits enfants. Le plus important de tout, c'est que les parents parlent beaucoup avec l'enfant. C'est pourquoi chaque parent devrait parler sa propre langue.","why":"Environ 85 mots, avec six des expressions. *denn* garde le verbe en 2e position (*lernen*) ; après *Deswegen*, le verbe vient tout de suite (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Résolvez les mots croisés. Chaque phrase donne la première lettre du mot manquant. La grille n'est pas affichée ici : tapez le mot en entier. Dans la grille du livre, Ä occupe une seule case.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Notre pays d'origine est l'Espagne. Nous venons d'Espagne.","why":"*aus einem Land stammen* = venir d'un pays (comme *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda et Mike ne se voient pas pendant six mois. C'est une longue séparation.","why":"*die Trennung* = la séparation, le nom de *sich trennen*. *eine lange* → un nom féminin."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"L'allemand et l'arabe n'ont pas la même écriture.","why":"*die Schrift* = l'écriture, les lettres dans lesquelles une langue s'écrit. L'arabe utilise un autre alphabet."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter vit maintenant en Amérique. Depuis qu'il y vit, il a beaucoup changé.","why":"*sich verändern* = changer (en parlant d'une personne). Perfekt : *hat sich verändert*. Le Ä occupe une seule case."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Elle écrit des livres. Elle est auteure de profession.","why":"*Sie* → la forme féminine en *-in* : *der Autor → die Autorin*. Pas d'article après *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Les enfants ne font pas leurs devoirs. C'est pourquoi leurs parents les grondent.","why":"*mit jemandem schimpfen* = gronder quelqu'un. Sujet au pluriel *die Eltern* → *schimpfen*. Après *Deshalb*, le verbe vient tout de suite."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Elle ne travaille que depuis quelques mois. Elle a encore peu d'expérience dans son métier.","why":"*die Erfahrung* = l'expérience. *wenig Erfahrung haben* = avoir peu d'expérience."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Maintenant, c'est le chaos. Tout est sens dessus dessous.","why":"*durcheinander sein* = être en désordre, mélangé. S'écrit en un seul mot."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Pour Ye-Jon, les sons P et F se ressemblent. Elle ne peut pas les distinguer.","why":"*unterscheiden* = distinguer. Avec *kann*, l'infinitif va à la fin. *tönen* est le mot suisse pour *klingen* (sonner)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Je pars en Grèce pendant les vacances, mais malheureusement je ne parle pas du tout grec.","why":"*Griechisch* = la langue grecque, avec une majuscule. *kein Griechisch können* = ne pas parler du tout grec."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Il ne mange que des légumes et du riz. Il mange exclusivement des légumes et du riz.","why":"*ausschliesslich* = exclusivement, rien d'autre que. Orthographe suisse avec *ss* ; en Allemagne, on l'écrit avec le s dur (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Mot solution (la ligne en surbrillance dans la grille) : langue maternelle","why":"Chaque mot donne une lettre de la ligne en surbrillance : stam**M**en, trenn**U**ng, schrif**T**, (T dans la grille), veränd**E**rt, auto**R**in, (S dans la grille), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Mon plus beau mot allemand","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque photo à un mot de l'encadré. Les points de couleur du livre indiquent l'article : bleu = der, vert = das, rouge = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un dessert à la crème au caramel)","why":"Nom suisse de la crème caramel. *Chöpfli* signifie en suisse allemand ‘petite tête’ (*Kopf*). Point vert → *das*.","source":"hueber-tr"},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – étoile filante","why":"*der Stern* = l'étoile ; *die Sternschnuppe* = l'étoile filante. Point rouge → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – papillon","why":"Mot suisse pour *der Schmetterling* (papillon) ; le Duden le marque *schweizerisch, sonst landschaftlich*. Point bleu → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Pourquoi quelqu'un pourrait-il trouver justement ces mots les plus beaux ? Qu'en pensez-vous ? Prenez des notes, puis discutez-en. Les notes modèles ne sont qu'une possibilité.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"si coloré et léger, rappelle l'été, drôle : l'animal n'est pas du tout un oiseau","why":"Pensez à ce que le mot vous fait voir ou ressentir, et à sa sonorité."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"doux, rappelle l'enfance, sonne drôle et typiquement suisse","why":"*tönen* = mot suisse pour *klingen* (sonner)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantique, on peut faire un vœu, sonne doux","why":"De courtes notes suffisent : des adjectifs et une raison."}]},{"no":"20","part":"c","part_instruction":"Hören Sie und vergleichen Sie. (Tracks 23–25)","part_instruction_en":"Écoutez et comparez avec vos notes de b. L'audio n'est pas sur ce site ; le résumé provient de la transcription officielle de Hueber.","items":[{"label":"1–3","text":"","open":true,"solution":"1 Die Frau: «Sommervogel» – sie denkt an den Sommer; lustig, denn das Tier ist kein Vogel, sondern ein Insekt. 2 Der Mann: «Caramelchöpfli» – er isst es gern und denkt an seine Kindheit und seine Grossmutter. 3 Der junge Mann: «Sternschnuppe» – man kann sich etwas wünschen, wenn man eine sieht.","en":"1 La femme : “Sommervogel” – elle pense à l'été ; drôle, car l'animal est un insecte, pas un oiseau. 2 L'homme : “Caramelchöpfli” – il adore en manger et pense à son enfance et à sa grand-mère. 3 Le jeune homme : “Sternschnuppe” – on peut faire un vœu quand on en voit une.","why":"Comparez : lesquelles de vos raisons de b les locuteurs ont-ils aussi données ?","source":"hueber-tr"}]},{"no":"20","part":"d","part_instruction":"Hören Sie noch einmal und ergänzen Sie.","part_instruction_en":"Écoutez encore une fois et complétez les trous.","items":[{"label":"1","text":"Die Frau ist Deutschlernerin. Sie findet das Wort ___ lustig, weil das Tier gar kein Vogel ist. Sie sagt, dass das Wort in ihrer Muttersprache sogar ___ tönt.","gaps":[["Sommervogel","«Sommervogel»"],["noch schöner","schöner"]],"solution":"Die Frau ist Deutschlernerin. Sie findet das Wort **Sommervogel** lustig, weil das Tier gar kein Vogel ist. Sie sagt, dass das Wort in ihrer Muttersprache sogar **noch schöner** tönt.","en":"La femme apprend l'allemand. Elle trouve le mot “Sommervogel” drôle parce que l'animal n'est pas du tout un oiseau. Elle dit que le mot sonne encore mieux dans sa langue maternelle.","why":"Transcription : *In meiner Muttersprache Italienisch ist das Wort sogar noch schöner: Farfalla!*","source":"hueber-tr"},{"label":"2","text":"Dem Mann gefällt das Wort ___ am besten, weil er diese gern isst. Dann erinnert er sich gern an seine ___, weil sie immer dieses süsse ___ gemacht hat.","gaps":[["Caramelchöpfli","«Caramelchöpfli»"],["Grossmutter","Grosi","Oma"],["Dessert","Caramelchöpfli"]],"solution":"Dem Mann gefällt das Wort **Caramelchöpfli** am besten, weil er diese gern isst. Dann erinnert er sich gern an seine **Grossmutter**, weil sie immer dieses süsse **Dessert** gemacht hat.","en":"L'homme aime surtout le mot “Caramelchöpfli” parce qu'il adore en manger. Alors il aime se souvenir de sa grand-mère, parce qu'elle faisait toujours ce dessert sucré.","why":"Transcription : *weil meine Grossmutter so gute Caramelchöpfli gemacht hat … ein süsses Dessert*. Il dit aussi *Kindheit*, mais *sie … gemacht hat* demande une personne.","source":"hueber-tr"},{"label":"3","text":"Der Mann findet, dass ___ das schönste deutsche Wort ist. Wenn man am Himmel ___, dann kann man sich etwas wünschen.","gaps":[["Sternschnuppe","«Sternschnuppe»"],["eine Sternschnuppe sieht","Sternschnuppen sieht"]],"solution":"Der Mann findet, dass **Sternschnuppe** das schönste deutsche Wort ist. Wenn man am Himmel **eine Sternschnuppe sieht**, dann kann man sich etwas wünschen.","en":"L'homme pense que “Sternschnuppe” est le plus beau mot allemand. Quand on voit une étoile filante dans le ciel, on peut faire un vœu.","why":"Transcription : *Weil man sich immer etwas wünschen kann, wenn man am Himmel eine Sternschnuppe sieht.* Dans la subordonnée en *wenn*, le verbe (*sieht*) va à la fin.","source":"hueber-tr"}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Mon mot préféré","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Quel mot allemand et quel mot de votre langue maternelle aimez-vous ? Pourquoi ? Écrivez un court texte en utilisant les expressions. La réponse modèle n'est qu'une possibilité.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Mon mot allemand préféré est “gemütlich” (douillet, chaleureux). Quand j'entends ce mot, je pense à une soirée d'hiver avec du thé, des bougies et des amis. C'est pourquoi je le trouve si beau. Il sonne doux et chaud. Dans ma langue maternelle, l'anglais, il n'y a pas de mot avec exactement ce sens. En anglais, j'aime le mot “sunshine”. Pour moi, c'est un mot joyeux, parce qu'il sonne clair et aimable.","why":"*Wenn …, dann* + verbe tout de suite (*denke ich*) ; *Deshalb* + verbe tout de suite (*finde ich*). Remplacez par votre propre langue maternelle et vos propres mots.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Présentez votre texte en classe. Le modèle montre une façon possible de commencer.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Aujourd'hui, j'aimerais vous présenter mon mot préféré. C'est le mot “gemütlich”. …","why":"Commencez par nommer le mot, puis lisez votre texte de a. *euch* pour les camarades de classe, *Ihnen* si vous parlez de façon formelle."}]}]}],"sources":[{"id":"hueber-tr","title":"Hueber : Schritte plus Neu 5 Schweiz – Transkriptionen zum Arbeitsbuch (Lektion 4, Übung 20 c und d)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Transkriptionen_AB.pdf"},{"id":"sommervogel","title":"Duden : Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]}];
